// 监听状态栏高度变化（横屏/热更新时）
watch(
	() => uni.getSystemInfoSync?.()?.statusBarHeight,
	(newVal) => {
		if (newVal != null) statusBarHeight.value = newVal;
	},
);

// ===== 暴露方法 =====

defineExpose({
	refresh: () => {
		statusBarHeight.value = uni.getSystemInfoSync?.().statusBarHeight || 0;
	},
	statusBarHeight,
	totalHeight,
});
</script>

