unpackage/dist/dev/.sourcemap/mp-weixin/common/plugins/platform.js.map:1:{"version":3,"file":"platform.js","sources":["common/plugins/platform.js"],"sourcesContent":["/**
 * 平台检测工具（条件编译 + 运行时降级）
 */

export const Platform = {
	get name() {
		// 编译时替换，零运行时开销
		// #ifdef H5
		return "h5";
		// #endif
		// #ifdef MP-WEIXIN
		return "mp-weixin";
		// #endif
		// #ifdef MP-ALIPAY
		return "mp-alipay";
		// #endif
		// #ifdef MP-BAIDU
		return "mp-baidu";
		// #endif
		// #ifdef MP-TOUTIAO
		return "mp-toutiao";
		// #endif
		// #ifdef MP-QQ
		return "mp-qq";
		// #endif
